import {jest} from '@jest/globals';

jest.unstable_mockModule('ajv', () => ({
  default: class {
    compile() {
      const validate = () => false;
      validate.errors = [{keyword: 'required', dataPath: '.address', params: {missingProperty: \"['city/name']\"}}];
      return validate;
    }
    errorsText() {
      return 'city/name required';
    }
  },
}));

describe('legacy required paths [specs/hal-engine-tool-input-validation/spec.md#3]', () => {
  it('logs a legacy missing property as a JSON pointer', async () => {
    const {setLogger} = await import('../../shared/logger.js');
    const {ToolRegistry} = await import('./registry.js');
    const warn = jest.fn();
    setLogger({debug: jest.fn(), info: jest.fn(), warn, error: jest.fn()});
    try {
      const registry = new ToolRegistry();
      registry.register({name: 'nested', description: 'Nested', inputSchema: {type: 'object'}}, async () => 'ok');
      await registry.execute('nested', {address: {}});
      expect(warn.mock.calls).toEqual([
        ['tool', 'input validation failed', expect.objectContaining({paths: ['/address/city~1name']})],
      ]);
    } finally {
      setLogger();
    }
  });
});
EOF
timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/tools/registry.legacy-required.test.ts"
